import { TestBed } from '@angular/core/testing';
import { WatchlistStore } from './watchlist-store';

function mkMovie(id: number) {
  return { id, title: `Movie ${id}`, release_date: '2024-01-01', poster_path: null, overview: 'overview' };
}

describe('WatchlistStore', () => {
  let service: WatchlistStore;

  beforeEach(() => {
    localStorage.clear();
    TestBed.configureTestingModule({});
    service = TestBed.inject(WatchlistStore);
  });

  it('should be created', () => {
    expect(service).toBeTruthy();
  });

  it('adds movies as unseen with seen: false', () => {
    service.add(mkMovie(1));
    expect(service.items().length).toBe(1);
    expect(service.count()).toBe(1);
    const item = service.items()[0];
    expect(item.id).toBe(1);
    expect(item.seen).toBe(false);
    expect(service.watchedCount()).toBe(0);
  });

  it('ignores duplicates when adding the same movie twice', () => {
    service.add(mkMovie(1));
    service.add(mkMovie(1));
    expect(service.items().length).toBe(1);
  });

  it('toggleWatched flips the seen flag and watchedCount counts seen items', () => {
    service.add(mkMovie(1));
    service.add(mkMovie(2));
    service.toggleWatched(1);
    expect(service.items().find(m => m.id === 1)?.seen).toBe(true);
    expect(service.items().find(m => m.id === 2)?.seen).toBe(false);
    expect(service.watchedCount()).toBe(1);
    service.toggleWatched(1);
    expect(service.items().find(m => m.id === 1)?.seen).toBe(false);
    expect(service.watchedCount()).toBe(0);
  });

  it('remove drops the movie from the list', () => {
    service.add(mkMovie(1));
    service.add(mkMovie(2));
    service.remove(1);
    expect(service.items().length).toBe(1);
    expect(service.items()[0].id).toBe(2);
    expect(service.count()).toBe(1);
  });

  it('loads persisted items and reads the seen flag', () => {
    localStorage.setItem('watchlist', JSON.stringify([
      { id: 1, title: 'Seen one', seen: true },
      { id: 2, title: 'Unseen one', seen: false },
    ]));
    TestBed.resetTestingModule();
    TestBed.configureTestingModule({});
    const fresh = TestBed.inject(WatchlistStore);
    expect(fresh.items().length).toBe(2);
    expect(fresh.watchedCount()).toBe(1);
    expect(fresh.items().find(m => m.id === 1)?.seen).toBe(true);
  });

  it('persists items under the seen key', () => {
    service.add(mkMovie(1));
    const tb = TestBed as unknown as { flushEffects?: () => void; tick?: () => void };
    if (typeof tb.tick === 'function') {
      tb.tick();
    } else if (typeof tb.flushEffects === 'function') {
      tb.flushEffects();
    }
    const raw = localStorage.getItem('watchlist');
    expect(raw).not.toBeNull();
    const parsed = JSON.parse(raw ?? '[]') as Array<Record<string, unknown>>;
    expect(parsed.length).toBe(1);
    expect(parsed[0]['seen']).toBe(false);
    expect('watched' in parsed[0]).toBe(false);
  });
});
```

